import {rankIcon} from './ranks.js';
import {escapeHtml as h,number} from './domain.js';
import {planetArt,civilizationBadge} from './art.js';
const money=v=>number(v)+' Þ';
const date=v=>new Intl.DateTimeFormat('fr-FR',{dateStyle:'short',timeStyle:'short'}).format(new Date(v));
const errorBox='<p class="form-error" role="alert" hidden></p>';
export function civilizationQuote(planet,quantity){
 const count=Number(quantity);if(!Number.isInteger(count)||count<1||count>40-planet.tail_level)return null;
 let cost=0;for(let n=planet.tail_level+1;n<=planet.tail_level+count;n++){if(!Number.isFinite(Number(planet.prices[n])))return null;cost+=Number(planet.prices[n]);}
 return {cost,days:count*3,lastLevel:planet.tail_level+count};
}
export function assimilationProgress(job,now){return Math.max(0,Math.min(100,(new Date(now)-new Date(job.started_at))/(new Date(job.finishes_at)-new Date(job.started_at))*100));}
const insignia=tier=>rankIcon(tier);
export function rankProgressView(rank,compact=false){
 if(!rank)return '';
 const next=rank.next,needed=next?Math.max(0,next.threshold-rank.score):0,start=rank.catalog[rank.tier].threshold;
 const progress=next?Math.max(0,Math.min(100,(rank.score-start)/(next.threshold-start)*100)):100;
 return `<section class="rank-progress ${compact?'compact':''}">${insignia(rank.tier)}<div class="rank-copy"><span class="eyebrow">VOTRE GRADE</span><h2>${h(rank.name)}</h2><div class="rank-score"><strong>${number(rank.score)}</strong> points${next?`<span>Prochain grade : ${h(next.name)}</span>`:'<span>Haut commandement de la flotte</span>'}</div><div class="rank-meter" role="progressbar" aria-label="Progression vers le prochain grade" aria-valuenow="${Math.round(progress)}" aria-valuemin="0" aria-valuemax="100"><i style="width:${progress}%"></i></div><p>${next?needed?`${number(needed)} points avant le prochain palier.`:'Palier de score atteint.':''}${next?.advanced_worlds?` ${Math.min(rank.advanced_worlds,3)}/3 mondes civ 15 · ${number(Math.min(rank.combat_points,2000))}/2 000 points de combat requis.`:''}</p></div>${compact?'':`<dl class="rank-breakdown"><div><dt>Civilisation</dt><dd>${number(rank.civilization_points)}</dd></div><div><dt>Forces produites</dt><dd>${number(rank.production_points)}</dd></div><div><dt>Pertes infligées</dt><dd>${number(rank.combat_points)}</dd></div></dl>`}</section>`;
}
export function civilizationInvestmentView(planet,serverNow,compact=false){
 if(!planet)return '';
 const job=planet.jobs[0],tail=planet.tail_level,max=tail>=40,quote=max?null:civilizationQuote(planet,1),progress=job?assimilationProgress(job,serverNow):0;
 return `<div class="civilization-investment ${compact?'compact':''}">${job?`<div class="assimilation-heading"><span>Civ ${planet.civilization} → <b>${job.target_level}</b></span><time datetime="${h(job.finishes_at)}">${date(job.finishes_at)}</time></div><div class="assimilation-track" role="progressbar" aria-label="Assimilation vers la civilisation ${job.target_level}" aria-valuenow="${Math.round(progress)}" aria-valuemin="0" aria-valuemax="100"><i style="width:${progress}%"></i></div><p class="assimilation-status">Assimilation en cours${planet.jobs.length>1?` · ${planet.jobs.length-1} niveau${planet.jobs.length>2?'x':''} en attente`:''}</p>${compact?'':`<div class="assimilation-reserve"><span>${money(planet.jobs.reduce((sum,j)=>sum+j.cost,0))} investis</span><span>Dernier niveau financé : ${tail}</span></div><details class="assimilation-queue"><summary>Voir la file d’assimilation</summary><ol>${planet.jobs.map((j,i)=>`<li><span>Civ ${j.target_level}</span><span>${i===0?'En cours':'En attente'}</span><time>${date(j.finishes_at)}</time></li>`).join('')}</ol></details>`}`:`<p class="assimilation-status">${planet.civilization>=40?'Civilisation au sommet':'Prête à se développer'}</p>`}${max?`<p class="civilization-max">${planet.civilization>=40?'Niveau 40 atteint':'Tous les niveaux sont financés'}</p>`:`<form data-civilization="invest" data-planet-id="${h(planet.id)}" data-level="${planet.civilization}" data-tail="${tail}"><label>Niveaux à financer<input type="number" name="quantity" min="1" max="${40-tail}" value="1" step="1" required></label><div class="civilization-quote"><strong data-civ-cost>${money(quote.cost)}</strong><small data-civ-delay>${quote.days} jours${job?' supplémentaires':''}</small></div><button class="secondary" type="submit">${job?'Ajouter à la file':'Investir'} →</button>${errorBox}</form>`}</div>`;
}
export function civilizationView(data,pending){
 if(!data)return '<p class="empty">Chargement des programmes de civilisation…</p>';
 const total=data.planets.reduce((s,p)=>s+p.civilization,0),jobs=data.planets.flatMap(p=>p.jobs);
 return `<div class="civilization-page">${rankProgressView(data.rank)}${pending?`<div class="civilization-pending"><p>Un investissement attend sa confirmation.</p><button class="secondary" id="retry-civilization">Reprendre l’investissement</button></div>`:''}${data.debt>0?'<p class="form-error">Les nouveaux investissements attendent la régularisation de l’entretien.</p>':''}<div class="civilization-summary"><span><b>${total}</b> niveau${total>1?'x':''} cumulé${total>1?'s':''}</span><span><b>${jobs.length}</b> niveau${jobs.length>1?'x':''} financé${jobs.length>1?'s':''}</span><span><b>${money(jobs.reduce((s,j)=>s+j.cost,0))}</b> en assimilation</span></div><section class="civilization-worlds">${data.planets.length?data.planets.map(p=>`<article class="civilization-world"><div class="civilization-world-identity"><img src="${planetArt(p.race+'_'+p.resource)}" alt="" width="104" height="104"><div><h2>${h(p.name)}</h2><span class="civilization-current">${civilizationBadge()}<b>${p.civilization}</b></span><p>Commerce local ×${new Intl.NumberFormat('fr-FR',{maximumFractionDigits:2}).format(1+.05*(p.civilization-1))}</p></div></div>${civilizationInvestmentView(p,data.server_now)}</article>`).join(''):'<p class="empty">Aucune planète sous votre contrôle.</p>'}</section><details class="rank-catalog"><summary>Grades du commandement</summary><ol>${data.rank.catalog.map(r=>`<li class="${r.tier===data.rank.tier?'current':''}"><span>${h(r.name)}</span><b>${number(r.threshold)} points</b>${r.advanced_worlds?'<small>3 mondes civ 15 et 2 000 points de combat</small>':''}</li>`).join('')}</ol></details></div>`;
}
export function bindCivilizationQuotes(root,data){
 root.querySelectorAll('form[data-civilization]').forEach(form=>{const planet=data.planets.find(p=>p.id===form.dataset.planetId),field=form.querySelector('input[name=quantity]');field.addEventListener('input',()=>{const quote=civilizationQuote(planet,field.value);form.querySelector('[data-civ-cost]').textContent=quote?money(quote.cost):'Quantité invalide';form.querySelector('[data-civ-delay]').textContent=quote?`${quote.days} jours${planet.jobs.length?' supplémentaires':''}`:'';});});
}
export const progressionHelp=`<h3>Civilisation et assimilation</h3><p>Chaque niveau demande trois jours d’assimilation. Civ 2 coûte 80 000 Þ ; atteindre le niveau n coûte arrondi(80 000 × (n − 1)^0,85). Le maximum est 40. Financer plusieurs niveaux les met en file et débite immédiatement leur coût total. Ils sont assimilés successivement, même hors connexion. Des planètes différentes peuvent progresser en parallèle. Ferros accélère les chantiers industriels, pas l’assimilation. Les niveaux améliorent le rendement commercial local et le recrutement ; ils ne multiplient pas les revenus civils ni l’entretien.</p><p>La progression apparaît dans Planètes et dans Civilisation. Un investissement ne peut être annulé ni remboursé. En cas de capture, les niveaux déjà acquis sont conservés, et les investissements inachevés de l’ancien propriétaire sont interrompus sans remboursement. Les mondes neutres ne progressent pas.</p><h3>Score et grades</h3><p>Le score additionne 100 points par niveau de civilisation actuellement contrôlé, les forces produites et les pertes infligées. Référence militaire : soldat 1, scout 4, bombardier 24, destroyer 32. La production rapporte 20 % de cette valeur, plafonnée à 40 % des points de civilisation ; les destructions rapportent la valeur entière, partagée selon la contribution réelle du camp. Les fractions sont conservées. Garnisons initiales, captures, chargements, débarquements et regroupements ne sont pas de la production. Les destructions de ses propres forces ou des forces de son clan ne donnent pas de points.</p><p>Deux mondes cumulant trois niveaux atteignent les 300 points d’Aspirant de Flotte. Les paliers deviennent progressivement plus exigeants jusqu’à Grand Amiral : 10 000 points, au moins trois mondes civ 15 et 2 000 points de combat. La production militaire vérifiable déjà livrée est reprise ; le recrutement et les destructions sont comptés à partir de l’activation de ce système. Le score suit les territoires actuels et peut baisser après une perte de planète ; le grade reflète ce score et ses conditions actuelles. Les grades sont honorifiques et n’accordent aucun bonus caché.</p>`;
